class Solution {
public:
    int waysToBuildRooms(vector<int>& prevRoom) {
        const long long MOD = 1e9 + 7;
        int n = prevRoom.size();
        vector<vector<int>> children(n);
        for (int v = 1; v < n; ++v) children[prevRoom[v]].push_back(v);
        vector<int> order;
        order.reserve(n);
        order.push_back(0);
        for (int head = 0; head < (int)order.size(); ++head) {
            int u = order[head];
            for (int c : children[u]) order.push_back(c);
        }
        vector<long long> fact(n + 1, 1), invFact(n + 1, 1);
        for (int i = 1; i <= n; ++i) fact[i] = fact[i - 1] * i % MOD;
        auto power = [&](long long b, long long e) {
            long long r = 1;
            b %= MOD;
            while (e) {
                if (e & 1) r = r * b % MOD;
                b = b * b % MOD;
                e >>= 1;
            }
            return r;
        };
        invFact[n] = power(fact[n], MOD - 2);
        for (int i = n; i >= 1; --i) invFact[i - 1] = invFact[i] * i % MOD;
        vector<long long> sz(n, 1), ways(n, 1);
        for (int idx = n - 1; idx >= 0; --idx) {
            int u = order[idx];
            long long total = 0, res = 1;
            for (int c : children[u]) {
                res = res * ways[c] % MOD;
                res = res * fact[sz[c] + total] % MOD;
                res = res * invFact[sz[c]] % MOD * invFact[total] % MOD;
                total += sz[c];
            }
            ways[u] = res;
            sz[u] = total + 1;
        }
        return (int)ways[0];
    }
};

