class Solution {
    public int waysToBuildRooms(int[] prevRoom) {
        final long MOD = 1_000_000_007L;
        int n = prevRoom.length;
        List<List<Integer>> children = new ArrayList<>();
        for (int i = 0; i < n; ++i) children.add(new ArrayList<>());
        for (int v = 1; v < n; ++v) children.get(prevRoom[v]).add(v);
        int[] order = new int[n];
        int head = 0, tail = 0;
        order[tail++] = 0;
        while (head < tail) {
            int u = order[head++];
            for (int c : children.get(u)) order[tail++] = c;
        }
        long[] fact = new long[n + 1], invFact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; ++i) fact[i] = fact[i - 1] * i % MOD;
        invFact[n] = pow(fact[n], MOD - 2, MOD);
        for (int i = n; i >= 1; --i) invFact[i - 1] = invFact[i] * i % MOD;
        long[] sz = new long[n], ways = new long[n];
        Arrays.fill(sz, 1);
        Arrays.fill(ways, 1);
        for (int idx = n - 1; idx >= 0; --idx) {
            int u = order[idx];
            long total = 0, res = 1;
            for (int c : children.get(u)) {
                res = res * ways[(int)c] % MOD;
                res = res * fact[(int)(sz[(int)c] + total)] % MOD;
                res = res * invFact[(int)sz[(int)c]] % MOD * invFact[(int)total] % MOD;
                total += sz[(int)c];
            }
            ways[u] = res;
            sz[u] = total + 1;
        }
        return (int)ways[0];
    }

    private long pow(long b, long e, long mod) {
        long r = 1;
        b %= mod;
        while (e > 0) {
            if ((e & 1) == 1) r = r * b % mod;
            b = b * b % mod;
            e >>= 1;
        }
        return r;
    }
}

