class Solution:
    def waysToBuildRooms(self, prevRoom: List[int]) -> int:
        MOD = 10 ** 9 + 7
        n = len(prevRoom)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[prevRoom[v]].append(v)
        order = [0]
        head = 0
        while head < len(order):
            u = order[head]
            head += 1
            order.extend(children[u])
        sz = [1] * n
        for u in reversed(order):
            for c in children[u]:
                sz[u] += sz[c]
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i % MOD
        ans = fact[n]
        for v in range(n):
            ans = ans * pow(sz[v], MOD - 2, MOD) % MOD
        return ans

